var i=`1174-chile-relleno`;var n=`world-1174`;var o=`MX`;var a=`central-america-caribbean`;var l=8;var r=77;var s={en:`Chile Relleno`,ua:`Фарширований перець чиле рельєно`};var h={en:`Chile Relleno is a dish from Mexico prepared with poblano pepper, oaxaca cheese, egg white, egg yolk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Фарширований перець чиле рельєно, страва кухні країни Мексика, яку готують із таких продуктів: перець поблано, сир оахака, яєчний білок, яєчний жовток. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 18 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 18 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:18,i:[[`poblano-pepper`,8,`pcs`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`oaxaca-cheese`,350,`g`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:12,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:9,i:[[`egg-white`,5,`pcs`],[`egg-yolk`,5,`pcs`],[`all-purpose-flour`,85,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,160,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 10 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 10 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:10,i:[[`tomato`,330,`g`],[`yellow-onion`,125,`g`]]}];var g={slug:i,id:n,country:`MX`,region:a,servings:8,minutes:77,title:s,text:h,steps:u};export{o as country,g as default,n as id,r as minutes,a as region,l as servings,i as slug,u as steps,h as text,s as title};